def land_perimeter(arr):
    count = 0
    for i in range(len(arr)):
        for j in range(len(arr[i])):
            if arr[i][j] == 'X':
                count += 4  # Each 'X' tile gets 4 edges counted
                if i > 0 and arr[i - 1][j] == 'X':
                    count -= 2  # A shared border edge counted twice
                if j > 0 and arr[i][j - 1] == 'X':
                    count -= 2
    return count
```
