def landPerimeter(grid):
    perimeter = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 'X':
                perimeter += 4
                if i > 0 and grid[i-1][j] == 'X':
                    perimeter -= 1
                if i < len(grid)-1 and grid[i+1][j] == 'X':
                    perimeter -= 1
                if j > 0 and grid[i][j-1] == 'X':
                    perimeter -= 1
                if j < len(grid[0])-1 and grid[i][j+1] == 'X':
                    perimeter -= 1
    return perimeter
```

